// Generic emitter for a project-component instance. Props emit in insertion
// order; a declared content slot emits a trailing lambda even when empty.
// K1: `mod.*` keys are never named args — they become `modifier = Modifier…`
// only when the component declares a `modifier: Modifier` parameter.
private fun emitComponentInstance(sb: StringBuilder, node: WidgetNode, indent: String, components: ComponentRegistry, parent: String?, imports: MutableSet<String>) {
  val spec = components.spec(node.type)
  val args = node.props.entries.filter { !it.key.startsWith("mod.") }
  val hasSlot = spec?.slots?.singleOrNull() != null
  val modifier = if (spec?.acceptsModifier == true) modifierExpr(node, parent, imports) else null
  if (args.isEmpty() && modifier == null) {
    if (!hasSlot && node.children.isEmpty()) { sb.append("$indent${node.type}()\n"); return }
    sb.append("$indent${node.type} {\n")
  } else {
    sb.append("$indent${node.type}(\n")
    modifier?.let { sb.append("$indent  modifier = $it,\n") }
    for ((k, v) in args) {
      // K2: a token is written as its reference where it fits the parameter's type.
      val token = (v as? Token)?.takeIf { spec == null || tokenFits(propSourceType(node.type, k, components), it.value) }
      token?.let { imports.addTokenImport(it, tokenKindOf(it.value)) }
      // K4: a template argument writes each token part as its reference.
      if (v is Template) imports.addTokenImport(v, "String")
      // K7: so does an arithmetic argument, each token operand.
      if (v is Arith) imports.addTokenImport(v, "Int")
      // An event's arity is its signature's (`(Int) -> Unit` takes one), not the action's arg.
      val eventParams = spec?.events?.firstOrNull { it.name == k }?.let { if (it.paramType != null) 1 else 0 }
      fun render(x: Any?, branch: Boolean): String = when (x) {
        is Token -> x.ref
        // K3: in an `if` branch an action is a reference or a parenthesized lambda.
        is Action -> (eventParams ?: if (x.arg == "it") 1 else 0).let { n -> if (branch) fmtActionBranch(x, n) else fmtAction(x, n) }
        is Bind -> bindRef(x.field)
        is Template -> fmtTemplate(x, ::bindRef)
        is Arith -> arithKotlin(x, ::bindRef)
        is String -> kotlinStringLiteral(x)
        is Boolean -> x.toString()
        is Int -> x.toString()
        is Double -> kotlinDoubleLiteral(x)
        is List<*> -> "listOf(" + x.joinToString(", ") { if (it is String) kotlinStringLiteral(it) else it.toString() } + ")"
        else -> x.toString()
      }
      // A branch token is written as its reference where it fits, like a plain one.
      fun branchValue(x: Any?): Any? =
        if (x is Token && (spec == null || tokenFits(propSourceType(node.type, k, components), x.value))) {
          imports.addTokenImport(x, tokenKindOf(x.value)); x
        } else if (x is Template || x is Arith) {
          imports.addTokenImport(x, if (x is Arith) "Int" else "String"); x
        } else {
          tokenValue(x)
        }
      val rendered = when {
        v is Conditional -> fmtConditional(v) { x -> render(branchValue(x), branch = true) }
        token != null -> render(token, branch = false)
        else -> render(tokenValue(v), branch = false)
      }
      sb.append("$indent  $k = $rendered,\n")
    }
    if (!hasSlot && node.children.isEmpty()) { sb.append("$indent)\n"); return }
    sb.append("$indent) {\n")
  }
  node.children.forEach { emitNode(sb, it, "$indent  ", components, node.type, imports) }
  sb.append("$indent}\n")
}
